import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int a = sc.nextInt();
        int b = sc.nextInt();
        String piece = s.substring(a, b);
        System.out.println("切出来的是 " + piece);
        System.out.println("这段有 " + piece.length() + " 颗");
    }
}
